Plan: copy the workbook, read cached values from `book1` and `book2`, and for each place in `book1!A3:A23` sum the matching row’s `book2!H:J`. Write the numeric totals as plain values into `book1!B3:B23`, leaving empty cells as `None`.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["book1"]
v1 = vals["book1"]
v2 = vals["book2"]

def to_number(x):
    if x is None:
        return 0.0
    if isinstance(x, bool):
        return 0.0
    if isinstance(x, (int, float)):
        return float(x)
    try:
        return float(str(x).strip())
    except Exception:
        return 0.0

def norm_key(x):
    if x is None:
        return None
    if isinstance(x, bool):
        return str(x)
    if isinstance(x, float) and x.is_integer():
        return str(int(x))
    return str(x).strip()

# Build lookup from book2: place -> sum of H, I, J
lookup = {}
for r in range(2, v2.max_row + 1):
    key = norm_key(v2.cell(row=r, column=1).value)
    if key is None or key == "":
        continue
    total = 0.0
    for c in (8, 9, 10):  # H, I, J
        total += to_number(v2.cell(row=r, column=c).value)
    lookup[key] = lookup.get(key, 0.0) + total

# Write results into book1!B3:B23
for r in range(3, 24):
    key = norm_key(v1.cell(row=r, column=1).value)
    if key is None or key == "":
        ws.cell(row=r, column=2).value = None
    else:
        total = lookup.get(key, 0.0)
        if abs(total) < 1e-12:
            total = 0.0
        ws.cell(row=r, column=2).value = total

wb.save(OUT)

print("lookup size:", len(lookup))
print("first results:", [ws.cell(row=r, column=2).value for r in range(3, 8)])
